#include "codane/loop.hpp"
namespace codane {LoopResult run_loop(AgentProvider&p,const AgentRequest&r,const LoopPolicy&x,Cancellation&c,const std::function<bool(const AgentResult&,int)>&accept){LoopResult z;int failures=0,stagnant=0;auto start=Clock::now();for(int i=1;i<=x.max_iterations&&!c.cancelled();++i){if(x.max_wall_time.count()&&Clock::now()-start>=x.max_wall_time)break;auto q=r;q.attempt=i;auto a=p.run(q,c.source.get_token());z.iterations=i;if(a.status==NodeState::Succeeded&&accept(a,i)){z.accepted=true;failures=0;stagnant=0;}else{++failures;++stagnant;}if(x.stagnation_limit&&stagnant>=x.stagnation_limit)break;if(failures>=x.max_consecutive_failures)break;}return z;}}
